/**
 * The memecoin bonding curve, bit-for-bit with `contracts/src/launch/CurveMath.sol` + `CurveConfigLib.sol` (plan
 * B.5.2). Pure bigint maths — no I/O. Every amount is in raw base units (the coin and pathUSD both have 6 decimals).
 *
 * Curve frame: token0 = coin, token1 = pathUSD; `price = pathUSD per coin = (sqrtPriceX96 / 2^96)^2`. Segments are
 * constant-liquidity pieces, so amounts come from v4-core's `SqrtPriceMath` (ported below from v4-core@46c6834, MIT).
 * Shared vectors: `curve.vectors.json` (generated by `scripts/launch/curve-vectors.ts`, asserted by `curve.test.ts`
 * here and by `contracts/test/tempo/launch/CurveMath.t.sol` against the Solidity).
 */

export const Q96 = 1n << 96n;
export const BPS = 10_000n;
const U256 = (1n << 256n) - 1n;
const U160 = (1n << 160n) - 1n;
export const MAX_SEGMENTS = 16;
export const MAX_FEE_PERIODS = 256n;
export const PROTOCOL_MIGRATION_BPS = 20n;
export const CORRECTION_DIVISOR = 10n;

export interface Segment { sqrtPriceUpperX96: bigint; liquidity: bigint }
/** Anti-snipe schedule (bps). mode 0 linear, 1 exponential; `n = ⌊elapsed / period⌋`; never below `base`. */
export interface FeeSchedule { base: number; start: number; period: number; reduction: number; mode: 0 | 1 }

export class CurveError extends Error {
  constructor(public readonly code: "BadSegments" | "ThresholdBeyondCurve" | "TrailingSegments" | "BadFeeSchedule" | "BeyondCurveStart" | "InvalidPriceOrLiquidity" | "PriceOverflow" | "NotEnoughLiquidity") {
    super(code);
  }
}

// ── FullMath / UnsafeMath ─────────────────────────────────────────────────────────────────────────────────────────

export const mulDiv = (a: bigint, b: bigint, d: bigint): bigint => (a * b) / d;
export const mulDivRoundingUp = (a: bigint, b: bigint, d: bigint): bigint => {
  const p = a * b;
  return p / d + (p % d === 0n ? 0n : 1n);
};
export const divRoundingUp = (a: bigint, b: bigint): bigint => a / b + (a % b === 0n ? 0n : 1n);

// ── SqrtPriceMath (v4-core@46c6834:src/libraries/SqrtPriceMath.sol) ──────────────────────────────────────────────────

function toUint160(x: bigint): bigint {
  if (x > U160) throw new CurveError("PriceOverflow");
  return x;
}

export function nextSqrtFromAmount0RoundingUp(sqrtP: bigint, liquidity: bigint, amount: bigint, add: boolean): bigint {
  if (amount === 0n) return sqrtP;
  const numerator1 = liquidity << 96n;
  const product = amount * sqrtP;
  if (add) {
    // Solidity's unchecked branch: taken when `amount * sqrtP` and `numerator1 + product` both fit 256 bits.
    if (product <= U256 && numerator1 + product <= U256) return toUint160(mulDivRoundingUp(numerator1, sqrtP, numerator1 + product));
    return toUint160(divRoundingUp(numerator1, numerator1 / sqrtP + amount));
  }
  if (product > U256 || numerator1 <= product) throw new CurveError("PriceOverflow");
  return toUint160(mulDivRoundingUp(numerator1, sqrtP, numerator1 - product));
}

export function nextSqrtFromAmount1RoundingDown(sqrtP: bigint, liquidity: bigint, amount: bigint, add: boolean): bigint {
  if (add) return toUint160(sqrtP + (amount * Q96) / liquidity);
  const quotient = divRoundingUp(amount * Q96, liquidity);
  if (sqrtP <= quotient) throw new CurveError("NotEnoughLiquidity");
  return sqrtP - quotient;
}

export function nextSqrtFromInput(sqrtP: bigint, liquidity: bigint, amountIn: bigint, zeroForOne: boolean): bigint {
  if (sqrtP === 0n || liquidity === 0n) throw new CurveError("InvalidPriceOrLiquidity");
  return zeroForOne ? nextSqrtFromAmount0RoundingUp(sqrtP, liquidity, amountIn, true) : nextSqrtFromAmount1RoundingDown(sqrtP, liquidity, amountIn, true);
}

export function amount0Delta(a: bigint, b: bigint, liquidity: bigint, roundUp: boolean): bigint {
  const [lo, hi] = a > b ? [b, a] : [a, b];
  if (lo === 0n) throw new CurveError("InvalidPriceOrLiquidity");
  const n1 = liquidity << 96n;
  const n2 = hi - lo;
  return roundUp ? divRoundingUp(mulDivRoundingUp(n1, n2, hi), lo) : mulDiv(n1, n2, hi) / lo;
}

export function amount1Delta(a: bigint, b: bigint, liquidity: bigint, roundUp: boolean): bigint {
  const diff = a > b ? a - b : b - a;
  return roundUp ? mulDivRoundingUp(liquidity, diff, Q96) : mulDiv(liquidity, diff, Q96);
}

// ── config derivation (CurveMath.derive + CurveConfigLib) ────────────────────────────────────────────────────────

export interface Derived { sqrtEnd: bigint; curveSupply: bigint; quoteToEnd: bigint }

export function derive(sqrtStart: bigint, segs: readonly Segment[], threshold: bigint): Derived {
  const n = segs.length;
  if (n === 0 || n > MAX_SEGMENTS || sqrtStart === 0n || threshold === 0n) throw new CurveError("BadSegments");
  let lower = sqrtStart;
  let curveSupply = 0n;
  let quoteToEnd = 0n;
  for (let i = 0; i < n; i++) {
    const s = segs[i]!;
    if (s.sqrtPriceUpperX96 <= lower || s.liquidity === 0n) throw new CurveError("BadSegments");
    const segQuote = amount1Delta(lower, s.sqrtPriceUpperX96, s.liquidity, true);
    if (quoteToEnd + segQuote >= threshold) {
      const sqrtEnd = quoteToEnd + segQuote === threshold ? s.sqrtPriceUpperX96 : nextSqrtFromInput(lower, s.liquidity, threshold - quoteToEnd, false);
      if (sqrtEnd === lower) throw new CurveError("BadSegments");
      if (i !== n - 1) throw new CurveError("TrailingSegments");
      curveSupply += amount0Delta(lower, sqrtEnd, s.liquidity, true);
      quoteToEnd += amount1Delta(lower, sqrtEnd, s.liquidity, true);
      return { sqrtEnd, curveSupply, quoteToEnd };
    }
    quoteToEnd += segQuote;
    curveSupply += amount0Delta(lower, s.sqrtPriceUpperX96, s.liquidity, true);
    lower = s.sqrtPriceUpperX96;
  }
  throw new CurveError("ThresholdBeyondCurve");
}

/** The v4 frame flip: pathUSD is currency0 there (`2^192 / sqrtCurve`). */
export const v4SqrtPrice = (sqrtCurve: bigint): bigint => (1n << 192n) / sqrtCurve;

/** Coin paired with the migration quote at the end price: `quoteNet · 2^192 / sqrtEnd²`, rounded up. */
export function migrationCoinFor(quote: bigint, migrationFeeBps: number, sqrtEnd: bigint): bigint {
  const net = quote - (quote * PROTOCOL_MIGRATION_BPS) / BPS - (quote * BigInt(migrationFeeBps)) / BPS;
  return mulDivRoundingUp(mulDivRoundingUp(net, Q96, sqrtEnd), Q96, sqrtEnd);
}

/** The least total supply `createConfig` accepts: curve + migration coin + the 10 % correction allowance. */
export const minTotalSupply = (curveSupply: bigint, migrationCoin: bigint): bigint => curveSupply + migrationCoin + migrationCoin / CORRECTION_DIVISOR;

// ── trading (CurveMath.buy / sell) ───────────────────────────────────────────────────────────────────────────────

export interface BuyResult { coinOut: bigint; quoteUsed: bigint; sqrtNext: bigint; segNext: number }
export interface SellResult { quoteOut: bigint; sqrtNext: bigint; segNext: number }

export function buy(segs: readonly Segment[], sqrtEnd: bigint, sqrtP: bigint, seg: number, quoteIn: bigint): BuyResult {
  let remaining = quoteIn;
  let coinOut = 0n;
  let quoteUsed = 0n;
  while (remaining !== 0n && sqrtP < sqrtEnd) {
    if (sqrtP === segs[seg]!.sqrtPriceUpperX96) seg++;
    const s = segs[seg]!;
    const upper = s.sqrtPriceUpperX96 < sqrtEnd ? s.sqrtPriceUpperX96 : sqrtEnd;
    const need = amount1Delta(sqrtP, upper, s.liquidity, true);
    if (remaining >= need) {
      coinOut += amount0Delta(sqrtP, upper, s.liquidity, false);
      quoteUsed += need;
      remaining -= need;
      sqrtP = upper;
    } else {
      const next = nextSqrtFromInput(sqrtP, s.liquidity, remaining, false);
      coinOut += amount0Delta(sqrtP, next, s.liquidity, false);
      quoteUsed += remaining;
      remaining = 0n;
      sqrtP = next;
    }
  }
  return { coinOut, quoteUsed, sqrtNext: sqrtP, segNext: seg };
}

export function sell(segs: readonly Segment[], sqrtStart: bigint, sqrtP: bigint, seg: number, coinIn: bigint): SellResult {
  let remaining = coinIn;
  let quoteOut = 0n;
  while (remaining !== 0n) {
    const lower = seg === 0 ? sqrtStart : segs[seg - 1]!.sqrtPriceUpperX96;
    const liq = segs[seg]!.liquidity;
    const need = amount0Delta(lower, sqrtP, liq, true);
    if (remaining >= need) {
      quoteOut += amount1Delta(lower, sqrtP, liq, false);
      remaining -= need;
      sqrtP = lower;
      if (seg === 0) {
        if (remaining !== 0n) throw new CurveError("BeyondCurveStart");
      } else seg--;
    } else {
      const next = nextSqrtFromInput(sqrtP, liq, remaining, true);
      quoteOut += amount1Delta(next, sqrtP, liq, false);
      remaining = 0n;
      sqrtP = next;
    }
  }
  return { quoteOut, sqrtNext: sqrtP, segNext: seg };
}

// ── fees ─────────────────────────────────────────────────────────────────────────────────────────────────────────

export function feeBps(f: FeeSchedule, elapsedSec: bigint): bigint {
  const base = BigInt(f.base);
  const start = BigInt(f.start);
  if (start === base) return base;
  const n = elapsedSec / BigInt(f.period);
  if (f.mode === 0) {
    const cut = n * BigInt(f.reduction);
    return cut >= start - base ? base : start - cut;
  }
  if (n > MAX_FEE_PERIODS) return base;
  let fee = start;
  for (let i = 0n; i < n && fee > base; i++) fee = (fee * (BPS - BigInt(f.reduction))) / BPS;
  return fee < base ? base : fee;
}

export const feeOn = (amount: bigint, bps: bigint): bigint => (amount * bps + BPS - 1n) / BPS;

export function grossFor(net: bigint, bps: bigint): bigint {
  let gross = (net * BPS + (BPS - bps) - 1n) / (BPS - bps);
  while (gross - feeOn(gross, bps) < net) gross++;
  return gross;
}

// ── quotes (CurveLaunchpad.quoteBuy / quoteSell) ─────────────────────────────────────────────────────────────────

export interface CurveState { sqrtPriceX96: bigint; segment: number }
export interface CurveShape { segments: readonly Segment[]; sqrtStartX96: bigint; sqrtEndX96: bigint }

export function quoteBuy(shape: CurveShape, state: CurveState, bps: bigint, quoteIn: bigint) {
  const net = quoteIn - feeOn(quoteIn, bps);
  const r = buy(shape.segments, shape.sqrtEndX96, state.sqrtPriceX96, state.segment, net);
  const quotePaid = r.quoteUsed === net ? quoteIn : min(grossFor(r.quoteUsed, bps), quoteIn);
  return { coinOut: r.coinOut, quotePaid, fee: quotePaid - r.quoteUsed, sqrtNext: r.sqrtNext, segNext: r.segNext, completes: r.sqrtNext === shape.sqrtEndX96 };
}

export function quoteSell(shape: CurveShape, state: CurveState, bps: bigint, coinIn: bigint) {
  const r = sell(shape.segments, shape.sqrtStartX96, state.sqrtPriceX96, state.segment, coinIn);
  const fee = feeOn(r.quoteOut, bps);
  return { quoteOut: r.quoteOut - fee, fee, sqrtNext: r.sqrtNext, segNext: r.segNext };
}

const min = (a: bigint, b: bigint) => (a < b ? a : b);

// ── design helpers ───────────────────────────────────────────────────────────────────────────────────────────────

/** Integer square root (floor). */
export function isqrt(n: bigint): bigint {
  if (n < 0n) throw new RangeError("isqrt of a negative");
  if (n < 2n) return n;
  // Newton's method from an upper bound (2^⌈bits/2⌉); monotonically decreasing to ⌊√n⌋.
  let x = 1n << BigInt(Math.ceil(n.toString(2).length / 2));
  for (;;) {
    const y = (x + n / x) >> 1n;
    if (y >= x) return x;
    x = y;
  }
}

/** sqrtPriceX96 for a price of `num/den` pathUSD per coin (raw units), floored. */
export const sqrtPriceX96For = (num: bigint, den: bigint): bigint => isqrt((num << 192n) / den);

/** Price (pathUSD per coin, 1e18-scaled) of a sqrtPriceX96, floored — for display. */
export const priceE18 = (sqrtX96: bigint): bigint => (sqrtX96 * sqrtX96 * 10n ** 18n) >> 192n;

/** The liquidity that makes `[sqrtA, sqrtB]` take `quote` pathUSD (floored). */
export const liquidityForQuote = (sqrtA: bigint, sqrtB: bigint, quote: bigint): bigint => (quote * Q96) / (sqrtB - sqrtA);

/** Progress to graduation in bps (reserve / threshold), capped at 10,000. */
export const progressBps = (quoteReserve: bigint, threshold: bigint): number => Number(min((quoteReserve * BPS) / threshold, BPS));
